function audio(){if(!ctx){ctx=new AudioContext();master=ctx.createGain();master.gain.value=+$('master').value;limiter=ctx.createDynamicsCompressor();limiter.threshold.value=-6;limiter.ratio.value=12;master.connect(limiter).connect(ctx.destination)}if(ctx.state==='suspended')ctx.resume().catch(()=>message('Click a pad to enable audio.',true));$('audioState').textContent='Audio ready';return ctx}
