function renderPads(){$('pads').replaceChildren();const b=bank(),dur=(b.end-b.start)/16;for(let p=0;p<16;p++){const el=document.createElement('button');el.className='pad'+(p===selectedPad?' selected':'');el.dataset.pad=p;el.setAttribute('aria-label',`Chop ${p+1}, key ${padKeys[p].toUpperCase()}`);el.innerHTML=`<span class="pad-number">${String(p+1).padStart(2,'0')}</span><kbd>${padKeys[p].toUpperCase()}</kbd><small>${(b.start+p*dur).toFixed(2)} — ${(b.start+(p+1)*dur).toFixed(2)} s</small>`;bindPlay(el,()=>({bankId:bank().id,pad:p,semitones:0}),`pad-pointer-${p}`);$('pads').append(el)}updateKeyboardHint()}
