function drawWave(){if(!bank())return;const canvas=$('waveform'),rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=Math.max(1,Math.floor(rect.width*ratio));canvas.height=Math.floor(rect.height*ratio);const g=canvas.getContext('2d'),w=canvas.width,h=canvas.height,b=bank(),d=b.buffer.getChannelData(0),start=Math.floor(b.start*b.buffer.sampleRate),end=Math.floor(b.end*b.buffer.sampleRate);g.clearRect(0,0,w,h);g.fillStyle='#c2ef771b';g.fillRect(w*selectedPad/16,0,w/16,h);g.strokeStyle='#627657';for(let i=0;i<=16;i++){g.beginPath();g.moveTo(i*w/16,0);g.lineTo(i*w/16,h);g.stroke()}g.fillStyle='#b4dc88';for(let x=0;x<w;x+=2*ratio){let min=0,max=0;const from=start+Math.floor(x/w*(end-start)),to=start+Math.floor((x+2*ratio)/w*(end-start));const step=Math.max(1,Math.floor((to-from)/24));for(let i=from;i<to;i+=step){const v=d[i]||0;min=Math.min(min,v);max=Math.max(max,v)}g.fillRect(x,h/2-max*h*.45,ratio,Math.max(ratio,(max-min)*h*.45))}}
const distortion=new Float32Array(8192);for(let i=0;i<distortion.length;i++){const x=i*2/(distortion.length-1)-1;distortion[i]=Math.tanh(x*4)}
