function setTransport(){const state=recording?'RECORDING':running?'PLAYING':'STOPPED';$('transportState').textContent=state;$('record').classList.toggle('active',recording);$('record').innerHTML=`<span></span> ${recording?'Finish take':running?'Overdub':'Record'}`;$('play').setAttribute('aria-label',running?'Pause loop':'Play loop');$('play').innerHTML=running?'<svg viewBox="0 0 24 24"><path d="M6 5h4v14H6zm8 0h4v14h-4Z"/></svg>':'<svg viewBox="0 0 24 24"><path d="m8 5 11 7-11 7Z"/></svg>';$('bpm').disabled=running;$('bars').disabled=running;$('loopHint').textContent=recording?'Recording into the selected MPC layer. Press Finish take to keep the loop playing.':running?'Loop playing. Select any MPC and press Overdub to add a layer.':'Press Record, play your pads, then press Record again to keep the loop running.'}
