const fxKeys={Shift:'repeat',q:'filter',w:'delay',e:'drive'};
function editable(e){return e.target.closest('input,textarea,select')}
document.addEventListener('keydown',e=>{if(editable(e)||e.ctrlKey||e.metaKey||e.altKey||(e.target.closest('button')&&(e.key===' '||e.key==='Enter')))return;const key=e.key==='Shift'?'Shift':e.key.toLowerCase();if(fxKeys[key]){e.preventDefault();setFx(fxKeys[key],true);return}if(e.repeat)return;if(key===' '){e.preventDefault();running?stop():start();return}if(key==='r'){e.preventDefault();$('record').click();return}const p=padKeys.indexOf(key);if(p>=0){e.preventDefault();press(`key-${key}`,{bankId:bank().id,pad:p,semitones:0});return}if(/^[0-8]$/.test(key)){e.preventDefault();const n=+key;press(`key-${key}`,{bankId:bank().id,pad:selectedPad,semitones:noteSemitones[n]+octave*12,note:n})}});
document.addEventListener('keyup',e=>{const key=e.key==='Shift'?'Shift':e.key.toLowerCase();if(fxKeys[key])setFx(fxKeys[key],false);release(`key-${key}`)});
window.addEventListener('blur',()=>{for(const token of [...held.keys()])release(token);for(const name of Object.keys(fx))setFx(name,false)});window.addEventListener('resize',drawWave);
function wav(buffer){const channels=buffer.numberOfChannels,length=buffer.length,result=new ArrayBuffer(44+length*channels*2),view=new DataView(result);const str=(pos,s)=>{for(let i=0;i<s.length;i++)view.setUint8(pos+i,s.charCodeAt(i))};str(0,'RIFF');view.setUint32(4,result.byteLength-8,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels,true);view.setUint32(24,buffer.sampleRate,true);view.setUint32(28,buffer.sampleRate*channels*2,true);view.setUint16(32,channels*2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,length*channels*2,true);const data=Array.from({length:channels},(_,i)=>buffer.getChannelData(i));for(let i=0;i<length;i++)for(let c=0;c<channels;c++){const value=Math.max(-1,Math.min(1,data[c][i]));view.setInt16(44+(i*channels+c)*2,value<0?value*32768:value*32767,true)}return new Blob([result],{type:'audio/wav'})}
$('exportLoop').onclick=async()=>{const button=$('exportLoop');button.disabled=true;button.textContent='Rendering…';try{audio();const duration=loopSeconds(),rate=44100,offline=new OfflineAudioContext(2,Math.ceil(duration*3*rate),rate),gain=offline.createGain(),comp=offline.createDynamicsCompressor();gain.gain.value=+$('master').value;comp.threshold.value=-6;comp.ratio.value=12;gain.connect(comp).connect(offline.destination);for(let cycle=0;cycle<3;cycle++)for(const b of banks)if(!b.muted)for(const event of b.events)playVoice(event,cycle*duration+event.beat*beatSeconds(),event.fx,offline,gain);const rendered=await offline.startRendering(),out=ctx.createBuffer(2,Math.ceil(duration*rate),rate);for(let c=0;c<2;c++){const tail=rendered.getChannelData(c).subarray(Math.floor(duration*2*rate),Math.floor(duration*2*rate)+out.length);out.getChannelData(c).set(tail.subarray(0,out.length));}const url=URL.createObjectURL(wav(out)),a=document.createElement('a');a.href=url;a.download=`chop-room-${$('bpm').value}bpm.wav`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);message('Loop exported as WAV.')}catch(e){message('Could not export this loop. Try a shorter loop and export again.',true)}finally{button.disabled=false;button.textContent='Export loop WAV'}};
// Demo audio is generated locally; it never requires a remote sample service.
addBank();$('audioState').textContent='Click a pad to play';
